import{_ as t}from"./chunks/clee-api-in-drupal.Wq3GJ01c.js";import{_ as a,c as o,o as r,ae as n}from"./chunks/framework.DBgX5bsf.js";const y=JSON.parse('{"title":"Payment Methods Management","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/commerce/paiements.md","filePath":"en/docs/commerce/paiements.md"}'),s={name:"en/docs/commerce/paiements.md"};function i(c,e,d,l,u,p){return r(),o("div",null,e[0]||(e[0]=[n('<h1 id="payment-methods-management" tabindex="-1">Payment Methods Management <a class="header-anchor" href="#payment-methods-management" aria-label="Permalink to &quot;Payment Methods Management&quot;">​</a></h1><p>We offer two payment methods: credit card payments and PayPal payments. These two methods are the most commonly used.</p><h2 id="credit-card-payment" tabindex="-1">Credit Card Payment <a class="header-anchor" href="#credit-card-payment" aria-label="Permalink to &quot;Credit Card Payment&quot;">​</a></h2><p>For this payment method, we use <strong>Stripe</strong> to process transactions. Stripe is an online payment platform that allows businesses of all sizes to securely accept online payments, including credit card payments.</p><h3 id="create-a-stripe-account" tabindex="-1">Create a Stripe Account <a class="header-anchor" href="#create-a-stripe-account" aria-label="Permalink to &quot;Create a Stripe Account&quot;">​</a></h3><p>To get started, you need to create a <strong>Stripe</strong> account. To do this, go to <a href="https://stripe.com/fr" target="_blank" rel="noreferrer">stripe.com</a> and follow the instructions.</p><h4 id="configure-your-account" tabindex="-1">Configure Your Account <a class="header-anchor" href="#configure-your-account" aria-label="Permalink to &quot;Configure Your Account&quot;">​</a></h4><ul><li><strong>Complete Your Profile</strong>: After validation, Stripe will ask you to provide additional information about your business (address, type of activity, etc.).</li><li><strong>Add a Bank Account</strong>: To receive payments, you must add a bank account where Stripe can transfer funds.</li></ul><h4 id="retrieve-api-keys" tabindex="-1">Retrieve API Keys <a class="header-anchor" href="#retrieve-api-keys" aria-label="Permalink to &quot;Retrieve API Keys&quot;">​</a></h4><ul><li><p><strong>Access the Dashboard</strong>: Once your account is set up, log in to your Stripe dashboard.</p></li><li><p><strong>Go to Developer Settings</strong>: In the left-hand menu, click on &quot;Developers.&quot;</p></li><li><p><strong>API Keys</strong>: Under the &quot;API keys&quot; tab, you will find your API keys:</p><ul><li><p>Publishable Key</p></li><li><p>Secret Key</p></li></ul></li></ul><h4 id="add-your-api-keys-to-your-store" tabindex="-1">Add Your API Keys to Your Store <a class="header-anchor" href="#add-your-api-keys-to-your-store" aria-label="Permalink to &quot;Add Your API Keys to Your Store&quot;">​</a></h4><p>In your Drupal site, go to <code>Commerce</code> &gt; <code>Configuration</code> &gt; <code>Commerce</code> &gt; <code>Payment Gateways</code> &gt; <code>Credit Card (Stripe)</code> and add your API keys.</p><p><img src="'+t+'" alt="Stripe"></p>',13)]))}const g=a(s,[["render",i]]);export{y as __pageData,g as default};
